1	export interface Scenario {
2	  customer: { yearsWithMHPCO: number };
3	  steps: Step[];
4	}
5	
6	export interface QuoteStep {
7	  op: "quote";
8	  items: { type: string; material?: string; enchantment?: number; cursed?: boolean }[];
9	}
10	
11	export type Step = QuoteStep;
12	
13	export interface ScenarioResults {
14	  results: ({ premium: number } | { payout: number; remainingCap: number })[];
15	}
16	
17	const PROCESSING_FEE = 5;
18	const BASE_PREMIUM_BY_TYPE: Record<string, number> = {
19	  sword: 100,
20	  amulet: 60,
21	  staff: 80,
22	  potion: 40,
23	  rune: 25,
24	};
25	const FIRST_INSURANCE_SURCHARGE = 0.1;
26	
27	// Percentage arithmetic leaves values like 71.00000000000001, which would
28	// otherwise round up to 72. Settle the float noise before rounding.
29	const FLOAT_NOISE_DIGITS = 6;
30	const withoutFloatNoise = (amount: number): number =>
31	  Number(amount.toFixed(FLOAT_NOISE_DIGITS));
32	
33	const roundUpInFavourOfMHPCO = (amount: number): number =>
34	  Math.ceil(withoutFloatNoise(amount));
35	
36	type Item = QuoteStep["items"][number];
37	
38	const basePremiumOf = (item: Item): number => BASE_PREMIUM_BY_TYPE[item.type];
39	
40	const increasedBy = (amount: number, rate: number): number =>
41	  amount * (1 + rate);
42	
43	const quotePremium = (step: QuoteStep): number => {
44	  const policyBasePremium = step.items.reduce(
45	    (sum, item) => sum + basePremiumOf(item),
46	    0,
47	  );
48	  return roundUpInFavourOfMHPCO(
49	    increasedBy(policyBasePremium, FIRST_INSURANCE_SURCHARGE) + PROCESSING_FEE,
50	  );
51	};
52	
53	export const runScenario = (scenario: Scenario): ScenarioResults => ({
54	  results: scenario.steps.map((step) => ({ premium: quotePremium(step) })),
55	});
