const policyBasePremiumOf = (items: Item[]): number =>
  items.reduce((sum, item) => sum + basePremiumOf(item), 0);

const quotePremium = (step: QuoteStep): number =>
  roundUpInFavourOfMHPCO(
    increasedBy(policyBasePremiumOf(step.items), FIRST_INSURANCE_SURCHARGE) +
      PROCESSING_FEE,
  );
